difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments (odd indices)
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0)
            translate([i * knuckle_pitch - knuckle_d/2,
                       knuckle_y,
                       knuckle_z])
                cylinder(d = knuckle_d, h = 6, $fn = 96); // 6 mm height

