    // Pin hole through every knuckle along the common X axis
    for (i = [0 : knuckle_n - 1]) {
        translate([i * knuckle_pitch - pin_d/2,
                   knuckle_y,
                   knuckle_z])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = 6 + 2 * eps, $fn = 64);
