```openscad
// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 50;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d     = 6;   // knuckle cylinder diameter
knuckle_count = 5;   // number of knuckle segments along X
knuckle_pitch = plate_len / knuckle_count;  // 10 mm segment length
knuckle_y     = 15;  // knuckle axis Y position (+Y edge)
knuckle_z     = 3;   // knuckle axis Z position (above plate)

// ---- Pin hole ----
pin_d = 2.5;         // pin hole diameter

// ---- Misc ----
eps = 0.5;           // overshoot for clean boolean cuts

// Plate body
module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

// Knuckle with pin hole, centred on a segment
module knuckle() {
    translate([-knuckle_pitch/2, 0, 0])
        difference() {
            cylinder(d = knuckle_d, h = knuckle_count, $fn = 64);
            translate([0, 0, -eps])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = knuckle_pitch + 2*eps);
        }
    // Shift to +Y edge
    translate([0, knuckle_y - 1, 0])
        translate([0, 0, knuckle_z])
            cylinder(d = knuckle_d, h = plate_thk + 0.5);
}

union() {
    plate();
    for (i = [0 : knuckle_count - 1])
        if (i % 2 == 0)  // 1st, 3rd, 5th segments
            knuckle();
}
