plate_t   = 4;     // plate thickness (mm)
hole_d    = 6;     // central through-hole diameter (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    polygon(points = concat(
        [for (i = [0 : point_n - 1])
            rotate(i * 360 / point_n) [outer_r, 0],
            rotate(i * 360 / point_n + 180 / point_n) [inner_r, 0]],
        [outer_r, 0]
    )),
    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Single point (reference) ----------------
// x = R cos(theta), y = R sin(theta)
function pt(R, theta) = [R * cos(theta), R * sin(theta)];
