difference() {
    // Square frustum body
    linear_extrude(height = height)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2])    square(top_size);
        }

    // Square pocket cut into the top face
    translate([0, 0, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
