        // Outer rim
        difference() {
            cylinder(h = part_thickness, r = outer_r);
            translate([0, 0, -cut_extra])
                cylinder(h = part_thickness + 2 * cut_extra, r = inner_r);
        }

        // Hub
        cylinder(h = part_thickness, r = hub_r);
    }

    // Axle hole through hub centre
    translate([0, 0, -cut_extra])
        cylinder(h = part_thickness + 2 * cut_extra, d = axle_hole_d);

    // Spokes (cut from hub outward to rim)
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / spoke_count])
            translate([hub_r - 0.01, -spoke_width / 2, 0])
                cube([outer_r - hub_r + 0.01,
                      spoke_width,
                      part_thickness]);
    }
