```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
point_n   = 6;     // number of points (star has this many outer and inner points)
plate_t   = 3;     // plate thickness (Z)
hole_d    = 6;     // central through-hole diameter
eps       = 0.5;   // overshoot for clean boolean cuts

$fn = 128;         // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    polygon(points = star_points(outer_r, inner_r, point_n));

    // Plate thickness
    translate([0, 0, -plate_t / 2])
        linear_extrude(height = plate_t)
            polygon(points = star_points(outer_r, inner_r, point_n));

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}

// ---------------- Helpers ----------------
// Generate vertices of a 2m-pointed star (outer/inner alternate)
function star_points(outer_r, inner_r, m) {
    res = [];
    for (i = [0 : m - 1]) {
        // outer point on angle i * 360 / m
        res += [
            [outer_r * cos(i * 360 / m), outer_r * sin(i * 360 / m)]
        ];
        // inner point on angle i * 360 / m + 180 / m (between outer points)
        res += [
            [inner_r * cos(i * 360 / m + 180 / m),
             inner_r * sin(i * 360 / m + 180 / m)]
        ];
    }
    return res;
}
