    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Alternate between outer and inner radii for the 2n vertices
function star_points(outer, inner, n) {
    res = [];
    for (i = [0 : n - 1]) {
        angle = i * 360 / n;
        push(res, [outer * cos(angle), outer * sin(angle)]);
        push(res, [inner * cos(angle + 180 / n),
                   inner * sin(angle + 180 / n)]);
    }
    return res;
}

function push(arr, v) {
    arr = arr || [];
    arr = arr + [v];
    return arr;
}
