// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
part_thickness   = 5;    // overall part thickness (Z)
rim_outer_d      = 80;   // outer diameter of rim
rim_width        = 4;    // rim width (radial)
hub_d            = 16;   // hub diameter
axle_hole_d      = 5;    // axle hole diameter (through hub)
spoke_count      = 4;    // number of spokes
spoke_width      = 4;    // spoke width (tangential)
spoke_start_ang  = 0;    // first spoke along +X axis (degrees)
