$fn              = 128;  // circle resolution

// ---------- Derived ----------
rim_inner_d = rim_outer_d - 2 * rim_width;  // 72 mm inner diameter
hub_r       = hub_d / 2;
spoke_len   = rim_inner_d / 2 + cut_extra;  // hub centre to rim inner edge

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = rim_outer_d, h = part_thickness);

        // Hub (overlaps rim slightly for a solid union)
        translate([0, 0, -cut_extra])
            cylinder(r = hub_r, h = part_thickness + 2 * cut_extra);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
                translate([0, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, part_thickness]);
        }
    }

    // Axle hole through hub centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
}
