        difference() {
            cylinder(d = wheel_od, h = wheel_w);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = wheel_w + 2 * eps);
        }

        // Hub with axle hole
        cylinder(d = hub_d, h = wheel_w);

        // Radial spokes, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([(wheel_od - hub_d) / 2 + 1, spoke_w, wheel_w]);
        }
    }

