plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_y   = 15;    // knuckle axis Y position (mm)
knuckle_z   = 4;     // knuckle axis Z position (mm)
knuckle_n   = 3;     // number of knuckle segments along X
knuckle_h   = plate_len / knuckle_n;  // segment length = 15 mm

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles: cylinders along X at 1st and 3rd segments
    for (seg = [0, 2]) {
        translate([seg * knuckle_h - knuckle_h/2, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = knuckle_h + 2*eps, center = true);

        // Pin hole through the knuckle
        translate([seg * knuckle_h - knuckle_h/2, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = knuckle_h + 2*eps, center = true);
    }
}
