                cylinder(d = knuckle_d, h = plate_thk + 0.5);
        }
    }

    // Pin hole along knuckle axis, through every knuckle
    translate([0, knuckle_y, 0])
        cylinder(d = pin_d, h = plate_thk + 2*eps);
}
