        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at specified height
        for (i = [0 : knuckle_count - 1]) {
            x0 = -plate_len/2 + i * knuckle_pitch;
            translate([x0, knuckle_axis_y, knuckle_axis_z])
                cylinder(d = knuckle_d, h = plate_thk + eps);
