        polygon(points = star_points(outer_r, inner_r, n_points));

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Evenly spaced angles, first on +X axis
function star_angles() {
    for (i = [0 : n_points - 1])
        yield i * 360 / n_points;
}

// Outline: outer point -> inner point -> outer point ...
function star_points(outer, inner, points) {
    out = [for (a = star_angles())
           [outer * cos(a), outer * sin(a)]];
    in_ = [for (a = star_angles())
           [inner * cos(a + 180 / points),
            inner * sin(a + 180 / points)]];
    return concat(out, in_);
}
