// inner/outer points evenly spaced in angle.
function star_points(outer_r, inner_r, n_points) =
    concat([
        [outer_r, 0],
        [inner_r * cos(360 / n_points), inner_r * sin(360 / n_points)]
    ],
    [for (i = [1 : n_points - 1])
        alternate_point(i, n_points, outer_r, inner_r)]);

