// ---------- Dimensions (mm) ----------
base_w     = 100;   // bottom square side length
base_h     = 100;   // bottom square side length (height used for extrusion)
top_w      = 80;    // top square side length
top_h      = 80;    // top square side length
block_h    = 30;    // overall height of frustum
eps        = 0.5;   // overshoot for clean boolean cuts

$fn = 64;           // curve resolution (no curved features, kept per convention)

// ---------- Model ----------
difference() {
    // Solid square frustum
    linear_extrude(height = block_h)
        polygon(points = [
            [-base_w/2, -base_h/2],
            [ base_w/2, -base_h/2],
            [ top_w/2,  top_h/2],
            [-top_w/2,  top_h/2]
        ]);

    // Square pocket in top face, centred
    translate([0, 0, block_h - 8])
        cube([70, 70, 8 + eps]);
}
