        // Rim
        cylinder(d = wheel_od, h = wheel_w);
        // Hub
        translate([0, 0, -0.01])
            cylinder(d = hub_d, h = wheel_w + 0.02);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([r_spoke + 1, spoke_w, wheel_w]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_w + 2 * eps);
