// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d     = 7;  // knuckle cylinder diameter
knuckle_count = 3;  // number of knuckle segments
knuckle_z     = 3.5; // knuckle axis height (z)
knuckle_y     = 10;  // knuckle axis y position (+Y edge)

// ---- Pin hole ----
pin_d = 3;          // pin hole diameter

// ---- Misc ----
eps = 0.5;          // overlap for clean boolean cuts

union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st and 3rd segments (indices 0 and 2)
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            x0 = -plate_len/2 + i * plate_len / knuckle_count;
