    // Star outline, centred on origin, first outer point on +X axis
    polygon(points = concat(
        [for (i = [0 : point_n - 1])
            [outer_r * cos(2 * pi * i / point_n),
             outer_r * sin(2 * pi * i / point_n)]],
        [for (i = [0 : point_n - 1])
            [inner_r * cos(2 * pi * (i + 0.5) / point_n),
             inner_r * sin(2 * pi * (i + 0.5) / point_n)])]
    );

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Finish ----------------
// No smoothing or quality flags: polygon vertices are exact,
// and the hole is round to the specified diameter.
