inner_r   = 17.5;  // distance of inner points from centre
plate_t   = 5;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

n_points  = 5;     // number of points (star is cyclic)
$fn       = 100;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid star plate
    linear_extrude(height = plate_t)
        polygon(points = star_points(outer_r, inner_r, n_points));

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Outline of a cyclic n-pointed star: outer points on +X, then alternating
function star_points(outer, inner, n) {
    pts = [];
    for (i = [0 : n - 1]) {
        a = i * 360 / n;
        pts += [rotate(a) [if (i % 2 == 0) outer else inner, 0]];
    }
    return pts;
}
