n_points  = 5;     // number of points (star is cyclic)
$fn       = 100;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid star outline, extruded
    linear_extrude(height = plate_t)
        polygon(points = star_points(outer_r, inner_r, n_points));

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Outline of a regular star: outer point on +X, then alternating
function star_points(outer, inner, p) {
    pts = [];
    for (i = [0 : p - 1]) {
        a = i * 360 / p;
        pts += [rotate([0, 0, a]) [if (i % 2 == 0) outer else inner, 0, 0]];
    }
    return pts;
}
