// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

// ---- Dimensions (mm) ----
outer_d      = 60;   // outer rim diameter
rim_width    = 5;    // rim width (also part thickness)
hub_d        = 14;   // hub diameter
axle_d       = 8;    // axle hole diameter
spoke_count  = 8;    // number of spokes
spoke_w      = 4;    // spoke width
eps          = 0.5;  // cutter overshoot

$fn = 128;

outer_r = outer_d / 2;
inner_r = outer_r - rim_width;  // rim inner radius
hub_r   = hub_d / 2;

difference() {
    // Outer rim
    cylinder(h = rim_width, r = outer_r);

    // Hub with axle hole
    translate([0, 0, -eps])
        cylinder(h = rim_width + 2 * eps, r = hub_r);

    // Radial spokes, first along +X axis
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_w / 2, 0])
                cube([(outer_r - hub_r) + 2, spoke_w, rim_width]);
}
