        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Evenly spaced angles, first point on +X axis
function star_angles(n) = [for (i = [0 : n - 1]) i * 360 / n];

// Outline: outer point, inner point, outer point, ...
function star_points(outer, inner, n) =
    [for (i = [0 : n - 1])
        concat(
            [outer * cos(star_angles(n)[i]), outer * sin(star_angles(n)[i])],
            [inner * cos(star_angles(n)[i + 1]), inner * sin(star_angles(n)[i + 1])]
        )];
