    linear_extrude(height = block_height)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2]) square(top_size);
        }

    // Square pocket in the top face
    translate([0, 0, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
