```openscad
// Spoked wheel for a small sample cart
// Flat part, printed lying on the bed, centred on the origin

// ---------------- Parameters ----------------
wheel_od      = 60;    // outer diameter of the rim (mm)
wheel_thick   = 5;     // overall part thickness (mm)
rim_width     = 4;     // rim ring width (mm)
hub_d         = 16;    // hub diameter (mm)
axle_d        = 5;     // axle hole diameter (mm)
spoke_count   = 5;     // number of spokes
spoke_w       = 5;     // spoke width (mm)
spoke_start   = 0;     // angle of first spoke (deg), 0 = +X axis
eps           = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;             // smoothness of curved shapes

// ---------------- Derived ----------------
rim_id = wheel_od - 2 * rim_width;   // inner diameter of rim (mm)
hub_r  = hub_d / 2;                  // hub radius (mm)

// ---------------- Model ----------------
difference() {
    // Outer disc
    cylinder(d = wheel_od, h = wheel_thick);

    // Rim ring cut out
    translate([0, 0, -eps])
        cylinder(d = rim_id, h = wheel_thick + 2 * eps);

    // Hub
    translate([0, 0, -eps])
        cylinder(r = hub_r, h = wheel_thick + 2 * eps);

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_thick + 2 * eps);

    // Spokes, radially from hub to rim, evenly spaced
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start + i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_w / 2, 0])
                cube([wheel_od / 2 - hub_r + 2, spoke_w, wheel_thick]);
}
```

