    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_width / 2, 0])
                cube([outer_r - hub_r + 2, spoke_width, part_thickness]);
