        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, and 5th segments
        for (i = [0 : 2 : knuckle_count - 1]) {
            x = -plate_len/2 + i * knuckle_pitch;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 6);
        }
    }

    // Pin hole along the knuckle axis, through all of them
    translate([-plate_len/2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
