block_h     = 20;    // overall block height
pocket_w    = 30;    // pocket square side length
pocket_d    = 5;     // pocket depth from top face
eps         = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Solid square frustum (hull between bottom and top faces)
    hull() {
        translate([-base_w/2, -base_w/2, 0])
            cube([base_w, base_w, block_h]);
        translate([-top_w/2, -top_w/2, block_h])
            cube([top_w, top_w, block_h]);
    }

    // Square pocket cut into the top face, centred
    translate([(top_w - pocket_w)/2, (top_w - pocket_w)/2, block_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
