// Star-shaped indexing wheel
// Print orientation: flat on bed, builds upward in +Z

// ---------------- Parameters ----------------
outer_r   = 35;    // radius of outer points (mm)
inner_r   = 17.5;  // radius of inner points (mm)
points    = 5;     // number of star points
thickness = 4;     // plate thickness (mm)
hole_d    = 8;     // central through-hole diameter (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;          // facet count for smooth curves

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    polygon(points = points * 2,
             r_a = outer_r,
             r_p = inner_r,
             angle = 0);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}

// ---------------- Helpers ----------------
// 5-pointed star outline (2D), counter-clockwise
module star_outline(outer_r, inner_r, points, angle = 0) {
    for (i = [0 : points - 1]) {
        // outer point on ray at angle i*72 + 0
        push([outer_r * cos(angle + i * 360 / points),
              outer_r * sin(angle + i * 360 / points)]);
        // inner point on ray at angle i*72 + 36
        push([inner_r * cos(angle + i * 360 / points + 36),
              inner_r * sin(angle + i * 360 / points + 36)]);
    }
}
