// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 35;    // distance of outer points from centre
inner_r   = 21;    // distance of inner points from centre
plate_t   = 5;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

n_points  = 8;     // number of (outer and inner) points
$fn       = 128;   // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline in XY, extruded to plate thickness
    linear_extrude(height = plate_t)
        polygon(points = star_points(outer_r, inner_r, n_points));

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 128);
}

// ---------------- Helpers ----------------
// Evenly spaced angles, first point on +X axis
function star_points(outer, inner, points) =
    [for (i = [0 : points - 1])
        [outer * cos((i * 360 / points)), outer * sin((i * 360 / points))],
     [for (i = [0 : points - 1])
        [inner * cos(((i + 0.5) * 360 / points)), inner * sin(((i + 0.5) * 360 / points))]]);
