    cylinder(d = outer_d, h = thickness);

    // Rim (keeps hub area thin)
    translate([0, 0, -eps])
        cylinder(d = outer_d - rim_w, h = thickness + 2 * eps);

    // Hub
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = thickness + 2 * eps);

    // Axle hole
    translate([0, 0, -1])
        cylinder(d = axle_d, h = thickness + 2);

    // Spokes
    for (i = [0 : spoke_n - 1])
        rotate([0, 0, i * 360 / spoke_n])
            translate([hub_d / 2, -spoke_w / 2, -eps])
                cube([outer_d - hub_d, spoke_w, thickness + 2 * eps]);
}
