// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters ----------------
wheel_od      = 60;   // outer diameter of the rim (mm)
wheel_width   = 6;    // rim thickness / part height (mm)
rim_width     = 4;    // width of the outer ring (mm)
hub_d         = 16;   // hub diameter (mm)
axle_hole     = 6;    // axle hole diameter (mm)
spoke_count   = 5;    // number of spokes
spoke_w       = 4;    // spoke width (mm)
eps           = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;             // smoothness of curved shapes

// ---------------- Derived ----------------
rim_id = wheel_od - 2 * rim_width;   // inner diameter of the rim (hub outer diameter)
spoke_len = wheel_od / 2 - hub_d / 2; // radial length of each spoke (mm)

// ---------------- Model ----------------
union() {
    // Outer rim (ring)
    difference() {
        cylinder(d = wheel_od, h = wheel_width);
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = wheel_width + 2 * eps);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_width);
        translate([0, 0, -eps])
            cylinder(d = axle_hole, h = wheel_width + 2 * eps);
    }

    // Radial spokes, first one along +X, evenly spaced
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, -spoke_w / 2, 0])
                cube([spoke_len, spoke_w, wheel_width]);
}
