// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
part_thickness   = 6;    // overall part thickness (Z)
rim_outer_d      = 60;   // outer diameter of rim
rim_width        = 4;    // rim width (tangential)
hub_d            = 16;   // hub diameter
axle_hole_d      = 6;    // central axle hole diameter
spoke_count      = 5;    // number of spokes
spoke_width      = 4;    // spoke width (radial)
spoke_start_ang  = 0;    // first spoke along +X axis
cut_extra        = 0.5;  // overshoot for clean boolean cuts
$fn              = 128;  // facet count for round features

// ---------- Derived ----------
rim_inner_d = rim_outer_d - 2 * rim_width;  // 52 mm
hub_r       = hub_d / 2;
axle_r      = axle_hole_d / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_outer_d, h = part_thickness);
            translate([0, 0, -cut_extra])
                cylinder(d = rim_inner_d, h = part_thickness + 2 * cut_extra);
        }

        // Hub
        cylinder(r = hub_r, h = part_thickness);
    }

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(r = axle_r, h = part_thickness + 2 * cut_extra);

    // Spokes, radially from hub to rim
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
            translate([hub_r - cut_extra, -spoke_width / 2, 0])
                cube([(rim_inner_d / 2 + cut_extra) - (hub_r - cut_extra),
                      spoke_width,
                      part_thickness]);
    }
}
