```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from centre (mm)
inner_r   = 15;    // distance of inner points from centre (mm)
plate_t   = 3;     // plate thickness (mm)
hole_d    = 6;     // central through-hole diameter (mm)
points    = 5;     // number of star points
eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    polygon(points = points * 2,
             vertices = concat(
                 [repeat(points, 2) * [r, 0],
                  rotate([0, 0, 90 / points]) repeat(points, 2) * [r, 0]]),
             r = [outer_r, inner_r]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// Helper (no side effects)
function repeat(n, k) {
    res = [];
    for (i = [0 : n - 1]) res = concat(res, [k, i]);
    return res;
}
