hub_r          = hub_d / 2;

// Spokes run radially from hub to rim (overlap into rim for a clean union)
spoke_ext      = rim_inner_r + spoke_w / 2;

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = thickness, r = outer_r);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_inner_r);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([spoke_ext * cos(spoke_start + i * 360 / spoke_count),
                           spoke_ext * sin(spoke_start + i * 360 / spoke_count),
                           0])
                    cube([spoke_w, spoke_w, thickness]);
    }

    // Axle hole through hub centre
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
